1	/**
2	 * Core vocabulary of the sync, mirroring `CONTEXT.md` and part 4 of
3	 * `docs/design.md`.
4	 *
5	 * The one distinction to carry while reading everything else: an **edit** is a
6	 * human action (one form save, one Salesforce field change), while a
7	 * **change** is a single field moving to a single new value. The sync reasons
8	 * only about changes, because the field — not the record — is what conflicts
9	 * and what carries history (ADR 0002).
10	 */
11	
12	/** The two record kinds the exercise names. */
13	export type ObjectType = "Customer" | "Contact";
14	
15	/** Which system an edit was made in. Carried on a change for its whole life. */
16	export type Origin = "salesforce" | "portal";
17	
18	/**
19	 * Tiebreak rank inside the order key (design 7.2).
20	 *
21	 * Salesforce is 1 and the portal 0, so Salesforce wins an exact-millisecond
22	 * tie. That is the cheaper direction, not an arbitrary one: a losing portal
23	 * value costs nothing, while a losing Salesforce value obliges us to send a
24	 * repair write (design 8.3).
25	 */
26	export const ORIGIN_RANK: Readonly<Record<Origin, number>> = Object.freeze({
27	  portal: 0,
28	  salesforce: 1,
29	});
30	
31	/**
32	 * The comparable value that decides which of two changes to one field is
33	 * current (design 7.2). Compared left to right: time, then rank, then event
34	 * id.
35	 */
36	export interface OrderKey {
37	  /**
38	   * On a webhook, the payload's `occurredAt`. On a portal save,
39	   * `clock_timestamp()` of the saving transaction — never a time supplied by
40	   * the caller, which could be forged (assumption A9).
41	   */
42	  readonly occurredAtMs: number;
43	  /** `ORIGIN_RANK[origin]`. */
44	  readonly originRank: number;
45	  /**
46	   * The webhook's `eventId`, or the portal change id. Breaks a shared
47	   * millisecond arbitrarily but **stably**, which matters because a
48	   * redelivered event must rank the same way the second time.
49	   */
50	  readonly originEventId: string;
51	}
52	
53	/** What `applyChanges` decided about one field. */
54	export type FieldOutcome =
55	  /** Became the current value. Permanent history. */
56	  | "applied"
57	  /** A real edit that lost the order-key comparison. Permanent history. */
58	  | "superseded"
59	  /** Salesforce describing a write of ours. Operational log, not history. */
60	  | "echo"
61	  /** Salesforce restating a value we already hold. Operational log. */
62	  | "confirmed"
63	  /**
64	   * A field in the payload whose value equals the `sf_value` we already held,
65	   * so Salesforce did not actually change it (design 8.4). Not restamped, not
66	   * compared, not touched.
67	   */
68	  | "restatement";
69	
70	/** How an inbound event as a whole was accounted for. */
71	export type EventOutcome =
72	  | "applied"
73	  | "duplicate"
74	  | "echo"
75	  | "superseded"
76	  | "partial"
77	  | "restatement"
78	  | "rejected";
79	
80	/** Why a row is sitting in the outbound queue. */
81	export type OutboundReason = "portal-edit" | "repair" | "create" | "recovery";
82	
83	/** Lifecycle of an outbound queue row (design 4, 6.5). */
84	export type OutboundState = "pending" | "inflight" | "sent" | "failed";
85	
86	/** One field moving to one new value, attributed to one actor at one time. */
87	export interface Change {
88	  readonly field: string;
89	  /** Canonical form (design 7.3). Null means the field was cleared. */
90	  readonly value: string | null;
91	}
92	
93	/** The input to `applyChanges` — one edit, which is one or more changes. */
94	export interface ApplyChangesInput {
95	  readonly objectType: ObjectType;
96	  /** Our own identifier. The caller has already resolved the record link. */
97	  readonly portalId: string;
98	  readonly origin: Origin;
99	  /** The identified human or integration account. Part of history, not metadata. */
100	  readonly actor: string;
101	  /** See {@link OrderKey.occurredAtMs}. */
102	  readonly occurredAtMs: number;
103	  /** See {@link OrderKey.originEventId}. */
104	  readonly originEventId: string;
105	  /** Raw, un-canonicalised values as they arrived. */
106	  readonly rawChanges: Readonly<Record<string, string | null>>;
107	  /**
108	   * True when this event is a notification about a write of ours (design 9.2
109	   * rule L2, or 9.3's fence). An echo never changes a current value.
110	   */
111	  readonly isEcho?: boolean;
112	}
113	
114	/** What `applyChanges` did to one field. */
115	export interface AppliedField {
116	  readonly field: string;
117	  readonly outcome: FieldOutcome;
118	  readonly previousValue: string | null;
119	  readonly newValue: string | null;
120	  /** True when condition (d) of design 8.3 enqueued an outbound call. */
121	  readonly enqueuedOutbound: boolean;
122	}
123	
124	/** Raised when a webhook cannot be accepted. Carries the HTTP status to use. */
125	export class WebhookRejected extends Error {
126	  constructor(
127	    message: string,
128	    /** 400 for "this will never work", 500 for "our bug, please retry". */
129	    readonly status: 400 | 500,
130	    /** Machine-readable reason, for the demo's printed output and for metrics. */
131	    readonly reason: string,
132	  ) {
133	    super(message);
134	    this.name = "WebhookRejected";
135	  }
136	}
137	
138	/** Raised when the durable store cannot be read. Never swallowed. */
139	export class StoreReadError extends Error {
140	  constructor(message: string, readonly cause?: unknown) {
141	    super(message);
142	    this.name = "StoreReadError";
143	  }
144	}
145	
146	/** Raised when the durable store cannot be written. Never swallowed. */
147	export class StoreWriteError extends Error {
148	  constructor(message: string, readonly cause?: unknown) {
149	    super(message);
150	    this.name = "StoreWriteError";
151	  }
152	}
