  return {
    occurredAtMs,
    // Taken from the shared table rather than written as a literal here: the
    // rank is the *rule*, and two copies of a rule are one edit away from
    // disagreeing.
    originRank: ORIGIN_RANK[origin],
    originEventId,
  };
