  test("takes the rank from ORIGIN_RANK rather than restating it", () => {
    const sf = makeOrderKey(1_000, "salesforce", "evt_1");
    const portal = makeOrderKey(1_000, "portal", "chg_1");
    assert.deepEqual(sf, {
      occurredAtMs: 1_000,
      originRank: ORIGIN_RANK.salesforce,
      originEventId: "evt_1",
