test("a Salesforce value superseded by a newer portal value owes a repair", () => {
  withStore((store) => {
    createRecord(store, "Customer", "cust-1");

    // The portal edit goes first and owes nothing, because we have never
    // heard Salesforce's value for this field. That keeps the queue empty
    // until the Salesforce event below, so the repair being asserted is the
    // one condition (d) raised for the superseded change.
    feed(store, {
      objectType: "Customer",
      portalId: "cust-1",
      origin: "portal",
      actor: "finance.user",
      occurredAtMs: 2_000,
      originEventId: "chg_1",
      rawChanges: { status: "active" },
    });
    assert.deepEqual(outboundOf(store), []);

    const results = feed(store, {
      objectType: "Customer",
      portalId: "cust-1",
      origin: "salesforce",
      actor: "sales.user",
      occurredAtMs: 1_500,
      originEventId: "evt_1",
      rawChanges: { status: "Churned" },
    });

    assert.equal(fieldResult(results, "status").outcome, "superseded");
    assert.equal(fieldResult(results, "status").enqueuedOutbound, true);
    assert.equal(valuesOf(store, "Customer", "cust-1").status, "Active");

    // Salesforce has no merge logic (design 7.1), so a webhook we reject is
    // not a no-op: it is the discovery that Salesforce holds a value we
    // rejected, and nobody else will fix that.
    assert.deepEqual(
      outboundOf(store).map((r) => [r.field, r.reason, r.state, r.occurredAtMs]),
      [["status", "repair", "pending", 1_500]],
    );
  });
});

