    const results = feed(store, {
      objectType: "Contact",
      portalId: "c-1",
      origin: "salesforce",
      actor: "sales.user",
      occurredAtMs: 2_400,
      originEventId: "evt_2",
      rawChanges: { phone: "+919000000001" },
    });

    assert.equal(fieldResult(results, "phone").enqueuedOutbound, true);
    assert.deepEqual(
      outboundOf(store)
        .filter((r) => r.state === "pending")
        .map((r) => r.field),
